<?php
$heading='Kalender Seleksi';$kicker='AGENDA · JADWAL';$subtitle='Jadwal dari rekruter dan pengingat pribadi dalam satu kalender.';require ROOT.'/app/Views/components/heading.php';
$first=new DateTimeImmutable($bulan.'-01');$days=(int)$first->format('t');$offset=(int)$first->format('N')-1;
$all=[];foreach($jadwal as $j){$j['tipe']='Seleksi';$all[]=$j;}foreach($pengingat as $j){$j['tipe']='Pribadi';$all[]=$j;}
usort($all,fn($a,$b)=>strcmp($a['waktu'],$b['waktu']));$byDate=[];foreach($all as $j)$byDate[substr($j['waktu'],0,10)][]=$j;
?>
<div class="content-with-aside"><div class="stack"><section class="card"><div class="section-heading"><h2><?= e($first->format('F Y')) ?></h2><div class="actions"><a class="button secondary small" aria-label="Bulan sebelumnya" href="<?= e(url('kalender',['bulan'=>$first->modify('-1 month')->format('Y-m')])) ?>">←</a><a class="button text small" href="<?= e(url('kalender')) ?>">Hari ini</a><a class="button secondary small" aria-label="Bulan berikutnya" href="<?= e(url('kalender',['bulan'=>$first->modify('+1 month')->format('Y-m')])) ?>">→</a></div></div><div class="calendar-grid"><?php foreach(['Sen','Sel','Rab','Kam','Jum','Sab','Min'] as $d):?><div class="calendar-weekday"><?= $d ?></div><?php endforeach;?><?php for($i=0;$i<$offset;$i++):?><div class="calendar-day outside"></div><?php endfor;?><?php for($d=1;$d<=$days;$d++):$date=$bulan.'-'.str_pad((string)$d,2,'0',STR_PAD_LEFT);?><div class="calendar-day <?= $date===date('Y-m-d')?'today':'' ?>"><strong><?= $d ?></strong><?php foreach($byDate[$date]??[] as $event):?><a class="calendar-event <?= $event['tipe']==='Pribadi'?'personal':'' ?>" href="#agenda-<?= e($date) ?>" title="<?= e($event['judul']) ?>"><?= tanggal($event['waktu'],'H:i') ?> <?= e($event['judul']) ?></a><?php endforeach;?></div><?php endfor;?></div><p class="calendar-legend"><span>● Jadwal seleksi</span><span>● Pengingat pribadi</span></p></section><section class="card"><h2>Agenda bulan ini</h2><?php $count=0;foreach($byDate as $date=>$events):if(substr($date,0,7)!==$bulan)continue;$count++;?><div id="agenda-<?= e($date) ?>" class="agenda-day"><h3><?= tanggal($date,'l, d M') ?></h3><?php foreach($events as $j):?><article class="agenda-detail"><div class="section-heading"><strong><?= e($j['judul']) ?></strong><span class="badge <?= $j['tipe']==='Pribadi'?'amber':'blue' ?>"><?= e($j['tipe']) ?></span></div><p><?= tanggal($j['waktu'],'H:i') ?> WIB <?= !empty($j['lokasi'])?'· '.e($j['lokasi']):'' ?></p><p class="muted"><?= e($j['catatan']) ?></p><?php if(!empty($j['namaLowongan'])):?><small><?= e($j['namaLowongan']) ?> · <?= e($j['namaMahasiswa']) ?></small><?php endif;?><div class="actions"><?php if($j['tipe']==='Pribadi'):?><a class="button text small" href="<?= e(url('kalender',['bulan'=>$bulan,'edit'=>$j['idPengingat']])) ?>">Ubah</a><form method="post" action="<?= e(url('kalender/hapus')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $j['idPengingat'] ?>"><button class="button text danger-text small">Hapus</button></form><?php elseif(!empty($j['tautan'])):?><a class="button secondary small" target="_blank" rel="noopener noreferrer" href="<?= e($j['tautan']) ?>">Buka Pertemuan ↗</a><?php endif;?><?php if($j['idLamaran']):?><a class="button text small" href="<?= e(url($currentUser['role']==='Rekruter'?'seleksi/detail':'lamaran/detail',['id'=>$j['idLamaran']])) ?>">Detail Lamaran →</a><?php endif;?></div></article><?php endforeach;?></div><?php endforeach;?><?php if(!$count):?><p class="muted">Belum ada agenda pada bulan ini.</p><?php endif;?></section></div>
<aside><section class="card"><h2><?= $edit?'Ubah':'Tambah' ?> Pengingat</h2><p class="muted">Pengingat pribadi hanya terlihat oleh akunmu.</p><form method="post" action="<?= e(url('kalender/simpan')) ?>"><?= csrf() ?><input type="hidden" name="idPengingat" value="<?= (int)($edit['idPengingat']??0) ?>"><label>Judul<input name="judul" maxlength="150" required value="<?= e($edit['judul']??'') ?>" placeholder="Persiapan wawancara"></label><label>Waktu (WIB)<input type="datetime-local" name="waktu" required value="<?= e(isset($edit['waktu'])?date('Y-m-d\TH:i',strtotime($edit['waktu'])):'') ?>"></label><label>Lamaran Terkait<select name="idLamaran"><option value="">Tanpa lamaran terkait</option><?php foreach($daftarLamaran as $a):if($a['statusLamaran']==='Draf')continue;?><option value="<?= $a['idLamaran'] ?>"<?= selected($edit['idLamaran']??'',$a['idLamaran']) ?>><?= e($a['namaLowongan'].($currentUser['role']==='Rekruter'?' · '.$a['namaMahasiswa']:'')) ?></option><?php endforeach;?></select></label><label>Catatan<textarea name="catatan" maxlength="2000" rows="4"><?= e($edit['catatan']??'') ?></textarea></label><button class="button full">Simpan Pengingat <?= icon('plus') ?></button><?php if($edit):?><a class="button text full" href="<?= e(url('kalender',['bulan'=>$bulan])) ?>">Batal Ubah</a><?php endif;?></form></section></aside></div>
